//answer, prayer pairs
const raw_prayers = [];
//can't let them clog up prayers by trying to leave them breaks prayers
const room_dibs_raw = [];

//created MANUALLY, keyed by roomId (different form scene id), value is array of prayers that made it
const finishedRoomPrayers = {};

//room dibs become this which scrapes them just to get the clownsona out
//the key is the first shot in the room, so any door that leads there will know to render clownsonas
const clown_signs_keyed_by_door = {};

const clean_answered_prayers = [];

const REFLECTED_MESSAGE = "Reflection of a Reflection Reflected Endlessly";
const ROOM_LITANY = "Dear, Sweet, Precious Harvest, I pray for a room to replace";

const getWaitingReflections = () => {
  const ret = [];
  for (let r of raw_prayers) {
    //im sure its fine
    if (r && r.prayerObject.message === REFLECTED_MESSAGE) {
      ret.push(r.prayerObject["save-data"])
    }
  }
  return ret;
}

const getDibsForRoom = (id) => {
  const ret = [];
  for (let r of room_dibs_raw) {
    //im sure its fine
    if (r && r.message.includes(ROOM_LITANY)) {
      try {
        const data = JSON.parse(r["save-data"]);
        if (data.current_room_id === id) {
          ret.push({ message: r.message, data })
        }
      } catch (e) {
        console.error(e);
      }
    }
  }
  return ret;
}


const getPendingPrayersForRoom = (id) => {
  const ret = [];
  const mail = fetchPendingCommands();
  for (let r of mail) {
    //im sure its fine
    if (r && r.message.includes(ROOM_LITANY)) {
      try {
        const data = JSON.parse(r["save-data"]);
        if (data.current_room_id === id) {
          ret.push({ message: r.message, data })
        }
      } catch (e) {
        console.error(e);
      }
    }
  }
  return ret;
}


const addNewReflection = (garbage, json) => {
  makeNewRawPrayer("Blessed", json)
}

//responses can be html, prayers can not be
//also if the prayer is a reflection, don't show spam
const autoMakeNewAnsweredPrayer = (prayer, response) => {
  if (!prayer || prayer === REFLECTED_MESSAGE) {
    return;
  }
  clean_answered_prayers.push({ prayer: prayer, response: response })
}
const makeNewRawPrayer = (responseText, prayerObject) => {
  raw_prayers.push({ response: responseText, prayerObject: prayerObject })
}

const addNewRoomDibs = (garbage, json) => {
  room_dibs_raw.push(json)
}

let specialReflectionCatSpiral;

const addNewClownSign = (garbage, json) => {
  const data = JSON.parse(json["save-data"]);
  //console.log("JR NOTE: addNewClownSign data", json.message)
  const key = data.current_room_id;
  const value = clown_signs_keyed_by_door[key];

  if (!value) {
    clown_signs_keyed_by_door[key] = [];
  }

  //TODO, need to parse out the dir but lets see this first
  clown_signs_keyed_by_door[key].push(data.clownsona.map((c) => `${doll_base}${c}`))

  if (data.hallways_entered === 1214 && data.lastLoadTimeCode === 1790899854384) {
    specialReflectionCatSpiral = data;
  }
}

const addNewFinishedRoomPrayer = (id, prayers) => {
  finishedRoomPrayers[id] = prayers;
}

